1. This is the hompage design we want to use: import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence, useMotionValue, useSpring } from 'framer-motion';
import { 
  ShieldCheck, 
  Users, 
  Zap, 
  ChevronRight, 
  Database,
  Activity,
  Globe,
  Ghost,
  Fingerprint,
  Mail,
  CheckCircle2,
  ExternalLink,
  ChevronLeft,
  Crosshair,
  Cpu,
  Maximize2,
  Search,
  Terminal,
  X
} from 'lucide-react';
import * as THREE from 'three';

// --- CLEAN NEURAL FABRIC BACKGROUND ---
const NeuralFabricBackground = () => {
  const containerRef = useRef();

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    containerRef.current.appendChild(renderer.domElement);

    camera.position.z = 15;

    const gridCount = 25;
    const geometry = new THREE.BufferGeometry();
    const positions = [];
    const step = 2.5;

    for (let i = -gridCount; i <= gridCount; i++) {
      positions.push(i * step, -gridCount * step, 0);
      positions.push(i * step, gridCount * step, 0);
      positions.push(-gridCount * step, i * step, 0);
      positions.push(gridCount * step, i * step, 0);
    }

    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    const material = new THREE.LineBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.015 });
    const grid = new THREE.LineSegments(geometry, material);
    scene.add(grid);

    const ambientLight = new THREE.AmbientLight(0xffffff, 1);
    scene.add(ambientLight);

    let frameId;
    const animate = () => {
      renderer.render(scene, camera);
      frameId = requestAnimationFrame(animate);
    };

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);
    frameId = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(frameId);
      if (containerRef.current) containerRef.current.removeChild(renderer.domElement);
      scene.clear();
      renderer.dispose();
    };
  }, []);

  return <div ref={containerRef} className="absolute inset-0 -z-10 bg-white" />;
};

// --- AGENT MOCK DATA ---
const AGENTS = [
  { id: 'master', name: 'Strategist', icon: Zap, x: 50, y: 50, parent: null, level: 0, theme: 'green' },
  { id: 'scout', name: 'Scout', icon: Globe, x: 38, y: 32, parent: 'master', level: 1, theme: 'green' },
  { id: 'sentinel', name: 'Sentinel', icon: ShieldCheck, x: 62, y: 32, parent: 'master', level: 1, theme: 'blue' },
  { id: 'anchor', name: 'Anchor', icon: Users, x: 50, y: 72, parent: 'master', level: 1, theme: 'blue' },
  { id: 'soul', name: 'Soul Agent', icon: Ghost, x: 25, y: 22, parent: 'scout', level: 2, theme: 'blue' },
  { id: 'stitcher', name: 'Identity Sync', icon: Activity, x: 38, y: 88, parent: 'anchor', level: 2, theme: 'blue' },
  { id: 'enricher', name: 'Data Sniper', icon: Fingerprint, x: 62, y: 88, parent: 'anchor', level: 2, theme: 'blue' },
  { id: 'recursive', name: 'Deep Researcher', icon: Crosshair, x: 75, y: 22, parent: 'sentinel', level: 2, theme: 'grey' },
];

const AGENT_LOGS = {
  scout: [
    { step: "Geo-fencing", finding: "Identified 42 fintech hubs in London E1." },
    { step: "Firmographic Scan", finding: "Series A status confirmed for 12 startups." },
    { step: "API Handshake", finding: "Connected to Netrows real-time proxy." }
  ],
  soul: [
    { step: "Handle Discovery", finding: "Mapped 4 leads to active GitHub/X profiles." },
    { step: "Sentiment Analysis", finding: "Found 3 pain-signals regarding RDS latency." },
    { step: "Intent Extraction", finding: "Extracted 2 technical complaints on Reddit." }
  ],
  master: [
    { step: "Mission Initialization", finding: "Recursive depth set to Level 3." },
    { step: "Task Delegation", finding: "Dispatched 6 worker nodes." },
    { step: "Confidence Scoring", finding: "Current threshold: 0.94" }
  ]
};

// --- HELPER COMPONENTS ---

const ConnectionLine = ({ agent, parent, swarmState }) => {
  const isParentDone = swarmState[parent.id]?.status === 'done';
  const isAgentActive = swarmState[agent.id]?.status === 'searching';
  const isAgentDone = swarmState[agent.id]?.status === 'done';

  const isActive = isParentDone && (isAgentActive || isAgentDone);
  const isCompleted = isAgentDone;

  return (
    <g key={`${agent.id}-edge`}>
      {/* Background Static Path (Faint) */}
      <line 
        x1={parent.x} 
        y1={parent.y} 
        x2={agent.x} 
        y2={agent.y} 
        stroke="black" 
        strokeWidth="0.2"
        className="opacity-5"
      />

      {/* Active Signal Logic */}
      {isActive && (
        <>
          {isCompleted ? (
            /* Completed: Solid Permanent Line */
            <motion.line
              initial={{ pathLength: 0 }}
              animate={{ pathLength: 1 }}
              x1={parent.x} 
              y1={parent.y} 
              x2={agent.x} 
              y2={agent.y} 
              stroke="#000" 
              strokeWidth="0.6"
              className="pointer-events-none"
            />
          ) : (
            /* In Progress: Pulsating Signal Line (Solid, No Dashes) */
            <>
              {/* Base Flow Line */}
              <line
                x1={parent.x} 
                y1={parent.y} 
                x2={agent.x} 
                y2={agent.y} 
                stroke="#3b82f6" 
                strokeWidth="0.6"
                className="opacity-20"
              />
              {/* Pulsating Glow Overlay */}
              <motion.line
                x1={parent.x} 
                y1={parent.y} 
                x2={agent.x} 
                y2={agent.y} 
                stroke="#60a5fa" 
                strokeWidth="1.2"
                initial={{ opacity: 0.2, strokeWidth: 0.6 }}
                animate={{ 
                  opacity: [0.2, 0.8, 0.2],
                  strokeWidth: [0.6, 1.4, 0.6]
                }}
                transition={{ 
                  duration: 2, 
                  repeat: Infinity, 
                  ease: "easeInOut" 
                }}
                className="pointer-events-none"
              />
            </>
          )}
        </>
      )}
    </g>
  );
};

const SwarmNode = ({ agent, status, dataCount, onInspect }) => {
  const Icon = agent.icon;
  const isActive = status === 'searching';
  const isDone = status === 'done';

  const themeClasses = {
    green: 'border-green-500 text-green-500 shadow-green-100/50',
    blue: 'border-blue-400 text-blue-400 shadow-blue-100/50',
    grey: 'border-neutral-100 text-neutral-300 shadow-none'
  };

  const currentTheme = isDone || isActive ? agent.theme : 'grey';

  return (
    <motion.div 
      initial={{ scale: 0, opacity: 0 }}
      animate={{ scale: 1, opacity: 1 }}
      className="absolute flex flex-col items-center select-none pointer-events-auto z-10"
      style={{ left: `${agent.x}%`, top: `${agent.y}%`, transform: 'translate(-50%, -50%)' }}
    >
      <div 
        className="relative cursor-pointer group"
        onClick={() => onInspect(agent)}
      >
        <div className={`relative w-14 h-14 md:w-20 md:h-20 rounded-full border-2 flex items-center justify-center bg-white shadow-2xl transition-all duration-700 
          ${themeClasses[currentTheme]}`}>
          <Icon size={agent.level === 0 ? 32 : 26} />
        </div>

        {dataCount > 0 && (
          <motion.div 
            initial={{ scale: 0 }} animate={{ scale: 1 }}
            className="absolute -top-1 -right-1 bg-black text-white text-[11px] font-black w-7 h-7 rounded-full flex items-center justify-center border-2 border-white z-20 shadow-md"
          >
            {dataCount}
          </motion.div>
        )}
      </div>
    </motion.div>
  );
};

// --- MAIN APP ---
export default function App() {
  const [view, setView] = useState('landing'); 
  const [progress, setProgress] = useState(0);
  const [swarmState, setSwarmState] = useState({});
  const [resultsOpen, setResultsOpen] = useState(false);
  const [inspectingNode, setInspectingNode] = useState(null);

  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const scale = useMotionValue(1);
  const springX = useSpring(x, { damping: 40, stiffness: 200 });
  const springY = useSpring(y, { damping: 40, stiffness: 200 });

  const dossiers = [
    { name: "Sarah Chen", title: "CTO @ Nebula AI", score: 9.8, hook: "Noticed your RDS latency tweet...", status: "Verified" },
    { name: "Marcus Thorne", title: "VP Engineering @ Quantix", score: 9.2, hook: "Your recent GitHub contribution...", status: "Verified" }
  ];

  const startHunt = () => {
    setView('hunting');
    setProgress(0);
    setSwarmState({ master: { status: 'searching', count: 1 } });
    x.set(0); y.set(0); scale.set(1);
  };

  useEffect(() => {
    if (view === 'hunting') {
      const timer = setInterval(() => {
        setProgress(p => {
          const next = p + 0.35;
          if (next > 4) setSwarmState(s => ({ ...s, master: { status: 'done', count: 1 } }));
          if (next > 15) setSwarmState(s => ({ ...s, scout: { status: 'searching', count: 8 }, sentinel: { status: 'searching', count: 2 } }));
          if (next > 42) setSwarmState(s => ({ ...s, scout: { status: 'done', count: 24 }, soul: { status: 'searching', count: 8 } }));
          if (next > 65) setSwarmState(s => ({ ...s, sentinel: { status: 'done', count: 2 }, recursive: { status: 'searching', count: 0 }, anchor: { status: 'searching', count: 12 } }));
          if (next > 85) setSwarmState(s => ({ ...s, soul: { status: 'done', count: 8 }, stitcher: { status: 'searching', count: 5 }, enricher: { status: 'searching', count: 2 } }));

          if (next >= 100) {
            clearInterval(timer);
            setSwarmState(() => {
                const final = {};
                AGENTS.forEach(a => final[a.id] = { status: 'done', count: Math.floor(Math.random() * 30) + 2 });
                return final;
            });
            setTimeout(() => setResultsOpen(true), 1500);
            return 100;
          }
          return next;
        });
      }, 50);
      return () => clearInterval(timer);
    }
  }, [view]);

  return (
    <div className="h-screen w-screen bg-white text-neutral-900 font-sans overflow-hidden relative selection:bg-black selection:text-white">
      <NeuralFabricBackground />

      {/* Navigation */}
      <nav className="absolute top-0 left-0 w-full p-10 flex justify-between items-center z-50 pointer-events-auto">
        <div className="flex items-center gap-4 cursor-pointer group" onClick={() => { setView('landing'); setResultsOpen(false); setInspectingNode(null); }}>
          <div className="w-10 h-10 bg-black rounded-full flex items-center justify-center transition-transform group-hover:scale-110">
            <Cpu className="text-white" size={18} />
          </div>
          <span className="font-black text-xl tracking-tighter uppercase">Leadgen 2026</span>
        </div>
        <div className="flex items-center gap-8">
          <button 
            onClick={() => setResultsOpen(!resultsOpen)}
            className="flex items-center gap-3 bg-neutral-100 px-6 py-3 rounded-full text-[10px] font-bold uppercase tracking-widest hover:bg-neutral-200 transition-all active:scale-95"
          >
            <Database size={14} /> Vault
          </button>
        </div>
      </nav>

      <AnimatePresence mode="wait">
        {view === 'landing' ? (
          <motion.main 
            key="landing"
            initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.95 }}
            className="h-full flex flex-col items-center justify-center px-10 text-center relative z-10"
          >
            <div className="max-w-4xl space-y-8">
              <h1 className="text-8xl md:text-9xl font-black tracking-tighter leading-[0.8] uppercase">
                Intelligence <br /> Swarm
              </h1>
              <p className="text-xl text-neutral-500 font-medium max-w-xl mx-auto leading-relaxed">
                Autonomous multi-agent discovery. Resolve identity and intent with high-fidelity OSINT swarms.
              </p>
              <div className="relative max-w-2xl mx-auto pt-10 group pointer-events-auto">
                <div className="absolute -inset-2 bg-neutral-100 rounded-3xl blur-2xl opacity-40 transition" />
                <div className="relative bg-white border border-neutral-100 rounded-2xl p-2 flex shadow-2xl items-center">
                    <div className="pl-6 text-neutral-300"><Search size={22} /></div>
                    <input 
                      type="text" 
                      placeholder="Input Mission DNA..."
                      className="flex-1 bg-transparent px-6 py-6 text-xl font-medium outline-none placeholder:text-neutral-300"
                    />
                    <button 
                      onClick={startHunt}
                      className="bg-black text-white px-10 py-5 rounded-xl font-black uppercase tracking-widest text-[10px] hover:bg-neutral-800 transition-all flex items-center gap-3"
                    >
                      Initiate <ChevronRight size={18} />
                    </button>
                </div>
              </div>
            </div>
          </motion.main>
        ) : (
          <motion.main 
            key="hunting"
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="h-full relative overflow-hidden flex items-center justify-center cursor-move"
          >
            <motion.div 
                drag
                style={{ x: springX, y: springY, scale }}
                className="w-full h-full relative flex items-center justify-center"
            >
                {/* SVG Connections with Center Alignment */}
                <svg 
                  viewBox="0 0 100 100" 
                  preserveAspectRatio="none"
                  className="absolute inset-0 w-full h-full pointer-events-none z-0"
                >
                    {AGENTS.map((agent) => {
                        if (!agent.parent) return null;
                        const parent = AGENTS.find(a => a.id === agent.parent);
                        return (
                          <ConnectionLine 
                            key={`${agent.id}-connection`} 
                            agent={agent} 
                            parent={parent} 
                            swarmState={swarmState} 
                          />
                        );
                    })}
                </svg>

                {AGENTS.map(agent => (
                    <SwarmNode 
                        key={agent.id} 
                        agent={agent} 
                        status={swarmState[agent.id]?.status || 'idle'}
                        dataCount={swarmState[agent.id]?.count || 0}
                        onInspect={setInspectingNode}
                    />
                ))}
            </motion.div>

            {/* Repositioned HUD */}
            <div className="absolute bottom-12 left-1/2 -translate-x-1/2 w-full max-w-sm px-6 text-center space-y-4 pointer-events-auto z-50">
                <div className="bg-white border border-neutral-100 rounded-[2.5rem] p-8 shadow-2xl">
