                            <span className="text-[9px] font-bold uppercase tracking-widest text-neutral-400">{progress < 100 ? 'Deep Research' : 'Finalizing Archive'}</span>
                        </div>
                        <button onClick={() => setView('landing')} className="text-[9px] font-bold uppercase tracking-widest text-neutral-300 hover:text-black transition-colors">Abort</button>
                    </div>
                </div>
            </div>

            {/* Interaction Controls */}
            <div className="absolute left-10 bottom-12 flex items-center gap-2 z-40">
                <button onClick={() => scale.set(scale.get() + 0.2)} className="w-10 h-10 bg-white border border-neutral-100 rounded-full shadow-md flex items-center justify-center hover:bg-neutral-50 font-bold">+</button>
                <button onClick={() => scale.set(Math.max(0.5, scale.get() - 0.2))} className="w-10 h-10 bg-white border border-neutral-100 rounded-full shadow-md flex items-center justify-center hover:bg-neutral-50 font-bold">-</button>
                <button onClick={() => { x.set(0); y.set(0); scale.set(1); }} className="w-10 h-10 bg-white border border-neutral-100 rounded-full shadow-md flex items-center justify-center hover:bg-neutral-50"><Maximize2 size={16} /></button>
            </div>
          </motion.main>
        )}
      </AnimatePresence>

      {/* Node Inspector Overlay */}
      <AnimatePresence>
        {inspectingNode && (
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.95 }}
            className="fixed inset-0 flex items-center justify-center z-[100] px-6 pointer-events-none"
          >
            <div className="bg-white border border-neutral-200 rounded-[2.5rem] shadow-2xl overflow-hidden p-10 w-full max-w-lg pointer-events-auto">
              <div className="flex justify-between items-start mb-10">
                <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-neutral-900 rounded-3xl flex items-center justify-center text-white shadow-xl shadow-black/10">
                        <inspectingNode.icon size={32} />
