                    <div>
                        <h2 className="font-black uppercase tracking-tighter text-2xl leading-none">Intelligence</h2>
                        <p className="text-[9px] font-bold uppercase text-neutral-400 tracking-widest mt-1">Resolution Archive</p>
                    </div>
                  </div>
                  <button onClick={() => setResultsOpen(false)} className="p-3 hover:bg-neutral-100 rounded-full transition-colors">
                    <ChevronLeft size={24} />
                  </button>
                </div>

                <div className="flex-1 overflow-y-auto space-y-6 pr-4 custom-scrollbar">
                  {dossiers.map((lead, i) => (
                    <motion.div 
                      key={lead.name}
                      initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.1 }}
                      className="group p-8 bg-white border border-neutral-100 rounded-[2rem] hover:border-black transition-all cursor-pointer relative overflow-hidden shadow-sm hover:shadow-xl"
                    >
                      <div className="flex justify-between items-start mb-6">
                        <div>
                            <h4 className="font-black text-2xl tracking-tighter mb-1">{lead.name}</h4>
                            <p className="text-xs text-neutral-500 font-medium">{lead.title}</p>
