                      <div className="space-y-4">
                        <div className="flex items-center gap-3 p-5 bg-neutral-50 rounded-2xl border border-neutral-100 group-hover:bg-white transition-colors">
                            <Zap size={16} className="text-neutral-900" />
                            <p className="text-sm italic font-medium text-neutral-600 line-clamp-2 leading-relaxed">"{lead.hook}"</p>
                        </div>
                        <div className="flex items-center justify-between text-[10px] font-bold uppercase tracking-widest pt-2">
                            <span className="text-green-600 flex items-center gap-2"><CheckCircle2 size={16} /> {lead.status}</span>
                            <span className="text-neutral-400 group-hover:text-black flex items-center gap-2 transition-colors">View Dossier <ExternalLink size={14} /></span>
                        </div>
                      </div>
                    </motion.div>
                  ))}
                </div>

                <div className="pt-10 mt-auto border-t border-neutral-100">
                    <button className="w-full bg-black text-white py-6 rounded-2xl font-black uppercase tracking-widest text-[11px] hover:bg-neutral-800 transition-all flex items-center justify-center gap-3 shadow-xl shadow-black/10">
                        Export Intelligence Payload <ChevronRight size={20} />
                    </button>
                </div>
              </div>
            </motion.aside>
          </>
        )}
      </AnimatePresence>

      {/* Background Subtle Grid Overlay */}
      <div 
        className="fixed inset-0 pointer-events-none z-0 opacity-[0.03]" 
        style={{ backgroundImage: `radial-gradient(circle, #000 1px, transparent 1px)`, backgroundSize: '60px 60px' }} 
      />
    </div>
  );
