@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;700&display=swap");

:root {
  --canvas: #f5f4f0;
  --surface: rgba(255, 255, 255, 0.86);
  --surface-strong: rgba(255, 255, 255, 0.96);
  --ink: #161616;
  --ink-soft: #4f4d49;
  --border: rgba(22, 22, 22, 0.09);
  --border-strong: rgba(22, 22, 22, 0.16);
  --shadow: 0 24px 70px rgba(17, 17, 17, 0.06);
  --radius-xl: 32px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --shell-width: 1200px;
}

html {
  font-size: 16px;
  min-height: 100%;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at top right, rgba(0, 0, 0, 0.05), transparent 28%),
    linear-gradient(180deg, #faf9f6 0%, var(--canvas) 100%);
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: inherit;
}

.shell {
  width: min(var(--shell-width), calc(100vw - 2rem));
  margin: 0 auto;
