  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 999px;
  background: var(--ink);
  color: white;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.stat-card__label,
.section-header__eyebrow,
.breadcrumb,
.mission-chip,
.metric-label,
.signal-item__meta {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.74rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.section-header__eyebrow,
.breadcrumb,
.metric-label,
.signal-item__meta {
  color: var(--ink-soft);
}

.brandmark__title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.site-nav__link,
.button-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1rem;
  border-radius: 999px;
  border: 1px solid transparent;
  transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
  font-size: 0.92rem;
}

.site-nav__link:hover,
.button-link:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.84);
  border-color: var(--border);
}

.site-nav__link--active {
  background: rgba(22, 22, 22, 0.9);
  color: white;
  border-color: rgba(22, 22, 22, 0.9);
}

.site-nav__link--active:hover {
  color: white;
  background: #262626;
  border-color: #262626;
}

.site-main {
  flex: 1;
  padding: 1.6rem 0 4rem;
}

.site-footer {
  padding: 0 0 2rem;
}

.site-footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
