@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;700&display=swap");

:root {
  --canvas: #f6f6f3;
  --surface: rgba(255, 255, 255, 0.9);
  --surface-strong: rgba(255, 255, 255, 0.98);
  --ink: #111111;
  --ink-soft: #616161;
  --border: rgba(17, 17, 17, 0.08);
  --border-strong: rgba(17, 17, 17, 0.16);
  --shadow: 0 28px 80px rgba(17, 17, 17, 0.05);
  --radius-xl: 32px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --shell-width: 1200px;
}

html {
  font-size: 16px;
  min-height: 100%;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at top right, rgba(0, 0, 0, 0.04), transparent 24%),
    radial-gradient(circle at left top, rgba(0, 0, 0, 0.02), transparent 20%),
    linear-gradient(180deg, #fbfbf8 0%, var(--canvas) 100%);
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: inherit;
}

.shell {
  width: min(var(--shell-width), calc(100vw - 2rem));
  margin: 0 auto;
}

.page-chrome {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 1rem 0 0;
  backdrop-filter: blur(18px);
}

.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.35rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: var(--shadow);
}

.brandmark {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
}

.brandmark__body {
  display: inline-flex;
  flex-direction: column;
  gap: 0.1rem;
}

.brandmark__seal {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 999px;
  background: var(--ink);
  color: white;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.stat-card__label,
.section-header__eyebrow,
.breadcrumb,
.mission-chip,
.metric-label,
.signal-item__meta {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.74rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.section-header__eyebrow,
.breadcrumb,
.metric-label,
.signal-item__meta {
  color: var(--ink-soft);
}

.brandmark__title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.site-nav__link,
.button-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1rem;
  border-radius: 999px;
  border: 1px solid transparent;
  transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
  font-size: 0.92rem;
}

.site-nav__link:hover,
.button-link:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.84);
  border-color: var(--border);
}

.site-nav__link--active {
  background: rgba(22, 22, 22, 0.9);
  color: white;
  border-color: rgba(22, 22, 22, 0.9);
}

.site-nav__link--active:hover {
  color: white;
  background: #262626;
  border-color: #262626;
}

.site-main {
  flex: 1;
  padding: 1.6rem 0 4rem;
}

.site-footer {
  padding: 0 0 2rem;
}

.site-footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 0 0;
  border-top: 1px solid var(--border);
}

.site-footer__title {
  font-weight: 700;
}

.site-footer__copy {
  color: var(--ink-soft);
  font-size: 0.95rem;
}

.site-footer__link {
  color: var(--ink-soft);
}

.dashboard {
  display: grid;
  gap: 1.5rem;
}

.dashboard--orbit {
  gap: 1.75rem;
}

.hero-panel,
.surface-panel,
.stat-card,
.mission-card,
.lead-card,
.signal-card,
.surface-score-card,
.detail-panel {
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.mission-stage {
  position: relative;
  overflow: hidden;
  padding: clamp(1.5rem, 3.4vw, 2.8rem);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius-xl) + 8px);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 255, 255, 0.9)),
    radial-gradient(circle at right top, rgba(0, 0, 0, 0.05), transparent 30%);
  box-shadow: var(--shadow);
}

.mission-stage__noise {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(17, 17, 17, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(17, 17, 17, 0.04) 1px, transparent 1px);
  background-size: 3.75rem 3.75rem;
  mask-image: radial-gradient(circle at center, black, transparent 82%);
  opacity: 0.45;
}

.mission-stage__grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.8fr);
  gap: 1.4rem;
  align-items: start;
}

.mission-stage__copy {
  position: relative;
  z-index: 1;
}

.mission-stage__copy h1 {

(() => {
  const initVaultSheets = () => {
    const openVault = (id) => {
      const panel = document.getElementById(id);
      const overlay = document.querySelector(`[data-vault-close="${id}"].vault-overlay`);
      if (!panel || !overlay) {
        return;
      }

      panel.classList.add("is-open");
      overlay.classList.add("is-open");
      panel.setAttribute("aria-hidden", "false");
    };

    const closeVault = (id) => {
      const panel = document.getElementById(id);
      const overlay = document.querySelector(`[data-vault-close="${id}"].vault-overlay`);
      if (!panel || !overlay) {
        return;
      }

      panel.classList.remove("is-open");
      overlay.classList.remove("is-open");
      panel.setAttribute("aria-hidden", "true");
    };

    document.querySelectorAll("[data-vault-open]").forEach((button) => {
      button.addEventListener("click", () => openVault(button.dataset.vaultOpen));
    });

    document.querySelectorAll("[data-vault-close]").forEach((button) => {
      button.addEventListener("click", () => closeVault(button.dataset.vaultClose));
    });

    document.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") {
        return;
      }

      document.querySelectorAll(".vault-sheet.is-open").forEach((panel) => {
        closeVault(panel.id);
      });
    });
  };

  const initMissionCanvas = () => {
    const canvasPage = document.querySelector("[data-mission-canvas]");
    if (!canvasPage) {
      return;
    }

    const progressValue = canvasPage.querySelector("[data-progress-value]");
    const progressBar = canvasPage.querySelector("[data-progress-bar]");
    const progressPhase = canvasPage.querySelector("[data-progress-phase]");
    const viewport = canvasPage.querySelector("[data-mission-viewport]");
    const nodes = new Map(
      Array.from(canvasPage.querySelectorAll("[data-node-role]")).map((node) => [
        node.dataset.nodeRole,
        node
      ])
    );

    const stages = [
      { role: "Strategist", start: 0, complete: 18, phase: "Mission routing" },
      { role: "Scout", start: 12, complete: 38, phase: "Deep research" },
      { role: "Sentinel", start: 22, complete: 52, phase: "Signal verification" },
      { role: "Anchor", start: 40, complete: 74, phase: "Identity resolution" },
      { role: "Soul", start: 56, complete: 86, phase: "Intent mining" },
      { role: "Stitcher", start: 72, complete: 96, phase: "Archive stitching" },
      { role: "Sniper", start: 84, complete: 100, phase: "Final verification" }
    ];

    let progress = Number(canvasPage.dataset.startingProgress || "14");
    let scale = 1;

    const setPhase = (value) => {
      let activePhase = "Archive ready";
      for (const stage of stages) {
        if (value < stage.complete) {
          activePhase = stage.phase;
          break;
        }
      }
      progressPhase.textContent = activePhase;
    };

    const updateNodes = (value) => {
      nodes.forEach((node) => {
        node.classList.remove("is-searching", "is-complete");
      });

      stages.forEach((stage, index) => {
        const node = nodes.get(stage.role);
        if (!node) {
          return;
        }

        const badge = node.querySelector(".mission-node__badge");
        if (badge) {
          badge.textContent = stage.role === "Strategist" ? "1" : String(index + 1);
        }

        if (value >= stage.complete) {
          node.classList.add("is-complete");
        } else if (value >= stage.start) {
          node.classList.add("is-searching");
        }
      });
    };

    const updateProgress = (value) => {
      const rounded = Math.max(0, Math.min(100, Math.floor(value)));
      progressValue.textContent = `${rounded}%`;
      progressBar.style.width = `${rounded}%`;
      setPhase(rounded);
      updateNodes(rounded);
    };

    const applyZoom = () => {
      viewport.style.setProperty("--mission-scale", scale.toFixed(2));
    };

    canvasPage.querySelectorAll("[data-zoom]").forEach((button) => {
      button.addEventListener("click", () => {
        const action = button.dataset.zoom;

        if (action === "in") {
          scale = Math.min(1.45, scale + 0.12);
        } else if (action === "out") {
          scale = Math.max(0.8, scale - 0.12);
        } else {
          scale = 1;
        }

        applyZoom();
      });
    });

    updateProgress(progress);
    applyZoom();

    const tick = () => {
      progress = Math.min(100, progress + 0.45);
      updateProgress(progress);

      if (progress < 100) {
        window.setTimeout(tick, 70);
      }
    };

    window.setTimeout(tick, 320);
  };

  initVaultSheets();
  initMissionCanvas();
})();

