﻿@using leadgen
@using leadgen.Models
@using leadgen.ViewModels.Home
@using leadgen.ViewModels.Missions
@using leadgen.ViewModels.ClarificationQuestions
@using leadgen.ViewModels.MissionRuns
@using leadgen.ViewModels.MissionAgentAssignments
@using leadgen.ViewModels.SwarmAgents
@using leadgen.ViewModels.TargetCompanies
@using leadgen.ViewModels.TargetContacts
@using leadgen.ViewModels.ContactChannels
@using leadgen.ViewModels.EvidencePoints
@using leadgen.ViewModels.LeadDossiers
@using Leadgen.Model.Entities
@addTagHelper *, Microsoft.AspNetCore.Mvc.TagHelpers

﻿@{
    Layout = "_Layout";
}

@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;700&display=swap");

:root {
  --canvas: #f6f6f3;
  --surface: rgba(255, 255, 255, 0.9);
  --surface-strong: rgba(255, 255, 255, 0.98);
  --ink: #111111;
  --ink-soft: #616161;
  --border: rgba(17, 17, 17, 0.08);
  --border-strong: rgba(17, 17, 17, 0.16);
  --shadow: 0 28px 80px rgba(17, 17, 17, 0.05);
  --radius-xl: 32px;
  --radius-lg: 22px;
  --radius-md: 16px;
  --shell-width: 1200px;
}

html {
  font-size: 16px;
  min-height: 100%;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at top right, rgba(0, 0, 0, 0.04), transparent 24%),
    radial-gradient(circle at left top, rgba(0, 0, 0, 0.02), transparent 20%),
    linear-gradient(180deg, #fbfbf8 0%, var(--canvas) 100%);
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: inherit;
}

.shell {
  width: min(var(--shell-width), calc(100vw - 2rem));
  margin: 0 auto;
}

.page-chrome {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  padding: 1rem 0 0;
  backdrop-filter: blur(18px);
}

.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.35rem;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: var(--shadow);
}

.brandmark {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
}

.brandmark__body {
  display: inline-flex;
  flex-direction: column;
  gap: 0.1rem;
}

.brandmark__seal {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 999px;
  background: var(--ink);
  color: white;
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.stat-card__label,
.section-header__eyebrow,
.breadcrumb,
.mission-chip,
.metric-label,
.signal-item__meta {
  font-family: "IBM Plex Mono", monospace;
  font-size: 0.74rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brandmark__eyebrow,
.eyebrow,
.section-header__eyebrow,
.breadcrumb,
.metric-label,
.signal-item__meta {
  color: var(--ink-soft);
}

.brandmark__title {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.site-nav__link,
.button-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1rem;
  border-radius: 999px;
  border: 1px solid transparent;
  transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease;
  font-size: 0.92rem;
}

.site-nav__link:hover,
.button-link:hover {
  transform: translateY(-1px);
  background: rgba(255, 255, 255, 0.84);
  border-color: var(--border);
}

.site-nav__link--active {
  background: rgba(22, 22, 22, 0.9);
  color: white;
  border-color: rgba(22, 22, 22, 0.9);
}

.site-nav__link--active:hover {
  color: white;
  background: #262626;
  border-color: #262626;
}

.site-main {
  flex: 1;
  padding: 1.6rem 0 4rem;
}

.site-footer {
  padding: 0 0 2rem;
}

.site-footer__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 0 0;
  border-top: 1px solid var(--border);
}

.site-footer__title {
  font-weight: 700;
